-- F21 Health — Training history management
-- Filename generated by Supabase CLI 3.1.0.
-- Provides auditable historical correction and logical deletion (voiding).
-- No hard delete is exposed to the client.

-- 1) RECORD STATUS / VOID METADATA

ALTER TABLE public.health_workout_sessions
ADD COLUMN record_status text NOT NULL DEFAULT 'active'
CHECK (record_status IN ('active','voided'));

ALTER TABLE public.health_workout_sessions
ADD COLUMN voided_at timestamptz NULL;

ALTER TABLE public.health_workout_sessions
ADD COLUMN void_reason text NULL;

ALTER TABLE public.health_workout_sessions
ADD COLUMN voided_by_auth_user_id uuid NULL
REFERENCES auth.users(id) ON DELETE SET NULL;

ALTER TABLE public.health_workout_sessions
ADD CONSTRAINT health_workout_sessions_void_consistency_check
CHECK (
  (
    record_status='active'
    AND voided_at IS NULL
    AND void_reason IS NULL
    AND voided_by_auth_user_id IS NULL
  )
  OR
  (
    record_status='voided'
    AND voided_at IS NOT NULL
    AND void_reason IS NOT NULL
    AND btrim(void_reason) <> ''
  )
);

CREATE INDEX health_workout_sessions_active_record_time_idx
ON public.health_workout_sessions(athlete_id, started_at DESC)
WHERE record_status='active';

ALTER TABLE public.health_activity_sessions
ADD COLUMN record_status text NOT NULL DEFAULT 'active'
CHECK (record_status IN ('active','voided'));

ALTER TABLE public.health_activity_sessions
ADD COLUMN voided_at timestamptz NULL;

ALTER TABLE public.health_activity_sessions
ADD COLUMN void_reason text NULL;

ALTER TABLE public.health_activity_sessions
ADD COLUMN voided_by_auth_user_id uuid NULL
REFERENCES auth.users(id) ON DELETE SET NULL;

ALTER TABLE public.health_activity_sessions
ADD CONSTRAINT health_activity_sessions_void_consistency_check
CHECK (
  (
    record_status='active'
    AND voided_at IS NULL
    AND void_reason IS NULL
    AND voided_by_auth_user_id IS NULL
  )
  OR
  (
    record_status='voided'
    AND voided_at IS NOT NULL
    AND void_reason IS NOT NULL
    AND btrim(void_reason) <> ''
  )
);

CREATE INDEX health_activity_sessions_active_record_time_idx
ON public.health_activity_sessions(athlete_id, started_at DESC)
WHERE record_status='active';

-- 2) AUDIT EVENT TYPES

ALTER TABLE public.health_workout_events
DROP CONSTRAINT health_workout_events_event_type_check;

ALTER TABLE public.health_workout_events
ADD CONSTRAINT health_workout_events_event_type_check
CHECK (
  event_type IN (
    'session_started','session_paused','session_resumed',
    'session_updated','session_voided',
    'exercise_added','exercise_skipped','exercise_replaced',
    'set_logged','set_updated','rest_recorded',
    'session_completed','session_aborted','note'
  )
);

ALTER TABLE public.health_activity_events
DROP CONSTRAINT health_activity_events_event_type_check;

ALTER TABLE public.health_activity_events
ADD CONSTRAINT health_activity_events_event_type_check
CHECK (
  event_type IN (
    'activity_started','activity_paused','activity_resumed',
    'activity_completed','activity_aborted',
    'activity_updated','activity_voided',
    'segment_added','note'
  )
);

-- 3) EDIT COMPLETED/ABORTED STRENGTH SESSION

CREATE OR REPLACE FUNCTION public.health_f21_update_workout_session(
  p_session_id uuid,
  p_client_event_id uuid,
  p_started_at timestamptz,
  p_ended_at timestamptz,
  p_notes text DEFAULT NULL
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_session public.health_workout_sessions%ROWTYPE;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'authentication required';
  END IF;

  SELECT *
  INTO v_session
  FROM public.health_workout_sessions
  WHERE id=p_session_id
  FOR UPDATE;

  IF v_session.id IS NULL THEN
    RAISE EXCEPTION 'workout session not found';
  END IF;

  IF NOT public.health_can_write_athlete(v_session.athlete_id) THEN
    RAISE EXCEPTION 'not authorized for athlete';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.health_workout_events ev
    WHERE ev.athlete_id=v_session.athlete_id
      AND ev.client_event_id=p_client_event_id
  ) THEN
    RETURN p_session_id;
  END IF;

  IF v_session.record_status<>'active' THEN
    RAISE EXCEPTION 'voided workout cannot be edited';
  END IF;

  IF v_session.status NOT IN ('completed','aborted') THEN
    RAISE EXCEPTION 'only closed workouts can be edited from history';
  END IF;

  IF p_started_at IS NULL OR p_ended_at IS NULL THEN
    RAISE EXCEPTION 'started_at and ended_at are required';
  END IF;

  IF p_ended_at < p_started_at THEN
    RAISE EXCEPTION 'ended_at must be greater than or equal to started_at';
  END IF;

  UPDATE public.health_workout_sessions
  SET
    started_at=p_started_at,
    ended_at=p_ended_at,
    notes=NULLIF(btrim(p_notes),'')
  WHERE id=p_session_id
    AND athlete_id=v_session.athlete_id;

  INSERT INTO public.health_workout_events (
    athlete_id,
    session_id,
    event_type,
    source,
    client_event_id,
    payload,
    created_by_auth_user_id
  )
  VALUES (
    v_session.athlete_id,
    p_session_id,
    'session_updated',
    'user',
    p_client_event_id,
    jsonb_build_object(
      'previous_started_at',v_session.started_at,
      'previous_ended_at',v_session.ended_at,
      'previous_notes',v_session.notes,
      'started_at',p_started_at,
      'ended_at',p_ended_at,
      'notes',NULLIF(btrim(p_notes),'')
    ),
    auth.uid()
  );

  RETURN p_session_id;
END;
$$;

-- 4) EDIT HISTORICAL STRENGTH SET

CREATE OR REPLACE FUNCTION public.health_f21_update_historical_set(
  p_set_id uuid,
  p_client_event_id uuid,
  p_load_value numeric,
  p_load_unit text,
  p_reps integer,
  p_rir numeric,
  p_rest_seconds integer DEFAULT NULL
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_set public.health_workout_sets%ROWTYPE;
  v_session public.health_workout_sessions%ROWTYPE;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'authentication required';
  END IF;

  SELECT *
  INTO v_set
  FROM public.health_workout_sets
  WHERE id=p_set_id;

  IF v_set.id IS NULL THEN
    RAISE EXCEPTION 'set not found';
  END IF;

  IF NOT public.health_can_write_athlete(v_set.athlete_id) THEN
    RAISE EXCEPTION 'not authorized for athlete';
  END IF;

  SELECT *
  INTO v_session
  FROM public.health_workout_sessions
  WHERE id=v_set.session_id
    AND athlete_id=v_set.athlete_id;

  IF v_session.id IS NULL THEN
    RAISE EXCEPTION 'workout session not found';
  END IF;

  IF v_session.record_status<>'active' THEN
    RAISE EXCEPTION 'voided workout cannot be edited';
  END IF;

  IF v_session.status NOT IN ('completed','aborted') THEN
    RAISE EXCEPTION 'only closed workouts can be edited from history';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.health_workout_events ev
    WHERE ev.athlete_id=v_set.athlete_id
      AND ev.client_event_id=p_client_event_id
  ) THEN
    RETURN p_set_id;
  END IF;

  UPDATE public.health_workout_sets
  SET
    load_value=p_load_value,
    load_unit=p_load_unit,
    reps=p_reps,
    rir=p_rir,
    rest_seconds=p_rest_seconds
  WHERE id=p_set_id
    AND athlete_id=v_set.athlete_id;

  INSERT INTO public.health_workout_events (
    athlete_id,
    session_id,
    workout_exercise_id,
    workout_set_id,
    event_type,
    source,
    client_event_id,
    payload,
    created_by_auth_user_id
  )
  VALUES (
    v_set.athlete_id,
    v_set.session_id,
    v_set.workout_exercise_id,
    v_set.id,
    'set_updated',
    'user',
    p_client_event_id,
    jsonb_build_object(
      'history_edit',true,
      'previous_load_value',v_set.load_value,
      'previous_load_unit',v_set.load_unit,
      'previous_reps',v_set.reps,
      'previous_rir',v_set.rir,
      'previous_rest_seconds',v_set.rest_seconds,
      'load_value',p_load_value,
      'load_unit',p_load_unit,
      'reps',p_reps,
      'rir',p_rir,
      'rest_seconds',p_rest_seconds
    ),
    auth.uid()
  );

  RETURN p_set_id;
END;
$$;

-- 5) VOID STRENGTH SESSION

CREATE OR REPLACE FUNCTION public.health_f21_void_workout_session(
  p_session_id uuid,
  p_client_event_id uuid,
  p_reason text
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_session public.health_workout_sessions%ROWTYPE;
  v_reason text;
  v_now timestamptz := clock_timestamp();
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'authentication required';
  END IF;

  v_reason := NULLIF(btrim(p_reason),'');
  IF v_reason IS NULL THEN
    RAISE EXCEPTION 'void reason is required';
  END IF;

  SELECT *
  INTO v_session
  FROM public.health_workout_sessions
  WHERE id=p_session_id
  FOR UPDATE;

  IF v_session.id IS NULL THEN
    RAISE EXCEPTION 'workout session not found';
  END IF;

  IF NOT public.health_can_write_athlete(v_session.athlete_id) THEN
    RAISE EXCEPTION 'not authorized for athlete';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.health_workout_events ev
    WHERE ev.athlete_id=v_session.athlete_id
      AND ev.client_event_id=p_client_event_id
  ) THEN
    RETURN p_session_id;
  END IF;

  IF v_session.record_status='voided' THEN
    RETURN p_session_id;
  END IF;

  IF v_session.status NOT IN ('completed','aborted') THEN
    RAISE EXCEPTION 'open workout cannot be voided from history';
  END IF;

  UPDATE public.health_workout_sessions
  SET
    record_status='voided',
    voided_at=v_now,
    void_reason=v_reason,
    voided_by_auth_user_id=auth.uid(),
    status=CASE WHEN status='completed' THEN 'aborted' ELSE status END
  WHERE id=p_session_id
    AND athlete_id=v_session.athlete_id;

  INSERT INTO public.health_workout_events (
    athlete_id,
    session_id,
    event_type,
    source,
    client_event_id,
    occurred_at,
    payload,
    created_by_auth_user_id
  )
  VALUES (
    v_session.athlete_id,
    p_session_id,
    'session_voided',
    'user',
    p_client_event_id,
    v_now,
    jsonb_build_object(
      'reason',v_reason,
      'previous_status',v_session.status,
      'queue_entry_id',v_session.queue_entry_id,
      'queue_rewound',false
    ),
    auth.uid()
  );

  RETURN p_session_id;
END;
$$;

-- 6) EDIT COMPLETED/ABORTED MULTIMODAL ACTIVITY

CREATE OR REPLACE FUNCTION public.health_f21_update_activity_session(
  p_activity_id uuid,
  p_client_event_id uuid,
  p_modality_code text,
  p_title text,
  p_started_at timestamptz,
  p_duration_seconds integer,
  p_distance_meters numeric DEFAULT NULL,
  p_calories_kcal numeric DEFAULT NULL,
  p_avg_hr_bpm integer DEFAULT NULL,
  p_max_hr_bpm integer DEFAULT NULL,
  p_rpe numeric DEFAULT NULL,
  p_cadence_spm numeric DEFAULT NULL,
  p_elevation_gain_m numeric DEFAULT NULL,
  p_steps integer DEFAULT NULL,
  p_notes text DEFAULT NULL
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_activity public.health_activity_sessions%ROWTYPE;
  v_title text;
  v_ended_at timestamptz;
  v_pace numeric := NULL;
  v_speed numeric := NULL;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'authentication required';
  END IF;

  SELECT *
  INTO v_activity
  FROM public.health_activity_sessions
  WHERE id=p_activity_id
  FOR UPDATE;

  IF v_activity.id IS NULL THEN
    RAISE EXCEPTION 'activity not found';
  END IF;

  IF NOT public.health_can_write_athlete(v_activity.athlete_id) THEN
    RAISE EXCEPTION 'not authorized for athlete';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.health_activity_events ev
    WHERE ev.athlete_id=v_activity.athlete_id
      AND ev.client_event_id=p_client_event_id
  ) THEN
    RETURN p_activity_id;
  END IF;

  IF v_activity.record_status<>'active' THEN
    RAISE EXCEPTION 'voided activity cannot be edited';
  END IF;

  IF v_activity.status NOT IN ('completed','aborted') THEN
    RAISE EXCEPTION 'only closed activities can be edited from history';
  END IF;

  IF p_started_at IS NULL THEN
    RAISE EXCEPTION 'started_at is required';
  END IF;

  IF p_duration_seconds IS NULL OR p_duration_seconds<=0 THEN
    RAISE EXCEPTION 'duration must be greater than zero';
  END IF;

  SELECT COALESCE(NULLIF(btrim(p_title),''),m.name)
  INTO v_title
  FROM public.health_activity_modalities m
  WHERE m.code=p_modality_code
    AND m.is_active=true;

  IF v_title IS NULL THEN
    RAISE EXCEPTION 'activity modality not found or inactive';
  END IF;

  v_ended_at := p_started_at+make_interval(secs=>p_duration_seconds);

  IF p_distance_meters IS NOT NULL
     AND p_distance_meters>0
     AND p_duration_seconds>0 THEN
    v_pace := p_duration_seconds/(p_distance_meters/1000.0);
    v_speed := (p_distance_meters/1000.0)/(p_duration_seconds/3600.0);
  END IF;

  UPDATE public.health_activity_sessions
  SET
    modality_code=p_modality_code,
    title=v_title,
    started_at=p_started_at,
    ended_at=v_ended_at,
    active_duration_seconds=p_duration_seconds,
    distance_meters=p_distance_meters,
    calories_kcal=p_calories_kcal,
    avg_hr_bpm=p_avg_hr_bpm,
    max_hr_bpm=p_max_hr_bpm,
    rpe=p_rpe,
    cadence_spm=p_cadence_spm,
    elevation_gain_m=p_elevation_gain_m,
    steps=p_steps,
    avg_pace_seconds_per_km=v_pace,
    avg_speed_kmh=v_speed,
    notes=NULLIF(btrim(p_notes),'')
  WHERE id=p_activity_id
    AND athlete_id=v_activity.athlete_id;

  INSERT INTO public.health_activity_events (
    athlete_id,
    activity_session_id,
    event_type,
    source,
    client_event_id,
    payload,
    created_by_auth_user_id
  )
  VALUES (
    v_activity.athlete_id,
    p_activity_id,
    'activity_updated',
    'user',
    p_client_event_id,
    jsonb_build_object(
      'history_edit',true,
      'previous_modality_code',v_activity.modality_code,
      'previous_title',v_activity.title,
      'previous_started_at',v_activity.started_at,
      'previous_duration_seconds',v_activity.active_duration_seconds,
      'modality_code',p_modality_code,
      'title',v_title,
      'started_at',p_started_at,
      'duration_seconds',p_duration_seconds,
      'distance_meters',p_distance_meters,
      'avg_pace_seconds_per_km',v_pace,
      'avg_speed_kmh',v_speed
    ),
    auth.uid()
  );

  RETURN p_activity_id;
END;
$$;

-- 7) VOID MULTIMODAL ACTIVITY

CREATE OR REPLACE FUNCTION public.health_f21_void_activity_session(
  p_activity_id uuid,
  p_client_event_id uuid,
  p_reason text
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_activity public.health_activity_sessions%ROWTYPE;
  v_reason text;
  v_now timestamptz := clock_timestamp();
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'authentication required';
  END IF;

  v_reason := NULLIF(btrim(p_reason),'');
  IF v_reason IS NULL THEN
    RAISE EXCEPTION 'void reason is required';
  END IF;

  SELECT *
  INTO v_activity
  FROM public.health_activity_sessions
  WHERE id=p_activity_id
  FOR UPDATE;

  IF v_activity.id IS NULL THEN
    RAISE EXCEPTION 'activity not found';
  END IF;

  IF NOT public.health_can_write_athlete(v_activity.athlete_id) THEN
    RAISE EXCEPTION 'not authorized for athlete';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.health_activity_events ev
    WHERE ev.athlete_id=v_activity.athlete_id
      AND ev.client_event_id=p_client_event_id
  ) THEN
    RETURN p_activity_id;
  END IF;

  IF v_activity.record_status='voided' THEN
    RETURN p_activity_id;
  END IF;

  IF v_activity.status NOT IN ('completed','aborted') THEN
    RAISE EXCEPTION 'open activity cannot be voided from history';
  END IF;

  UPDATE public.health_activity_sessions
  SET
    record_status='voided',
    voided_at=v_now,
    void_reason=v_reason,
    voided_by_auth_user_id=auth.uid(),
    status=CASE WHEN status='completed' THEN 'aborted' ELSE status END
  WHERE id=p_activity_id
    AND athlete_id=v_activity.athlete_id;

  INSERT INTO public.health_activity_events (
    athlete_id,
    activity_session_id,
    event_type,
    source,
    client_event_id,
    occurred_at,
    payload,
    created_by_auth_user_id
  )
  VALUES (
    v_activity.athlete_id,
    p_activity_id,
    'activity_voided',
    'user',
    p_client_event_id,
    v_now,
    jsonb_build_object(
      'reason',v_reason,
      'previous_status',v_activity.status
    ),
    auth.uid()
  );

  RETURN p_activity_id;
END;
$$;

-- 8) FUNCTION PERMISSIONS

REVOKE ALL ON FUNCTION public.health_f21_update_workout_session(uuid,uuid,timestamptz,timestamptz,text)
FROM PUBLIC, anon;
REVOKE ALL ON FUNCTION public.health_f21_update_historical_set(uuid,uuid,numeric,text,integer,numeric,integer)
FROM PUBLIC, anon;
REVOKE ALL ON FUNCTION public.health_f21_void_workout_session(uuid,uuid,text)
FROM PUBLIC, anon;
REVOKE ALL ON FUNCTION public.health_f21_update_activity_session(uuid,uuid,text,text,timestamptz,integer,numeric,numeric,integer,integer,numeric,numeric,numeric,integer,text)
FROM PUBLIC, anon;
REVOKE ALL ON FUNCTION public.health_f21_void_activity_session(uuid,uuid,text)
FROM PUBLIC, anon;

GRANT EXECUTE ON FUNCTION public.health_f21_update_workout_session(uuid,uuid,timestamptz,timestamptz,text)
TO authenticated;
GRANT EXECUTE ON FUNCTION public.health_f21_update_historical_set(uuid,uuid,numeric,text,integer,numeric,integer)
TO authenticated;
GRANT EXECUTE ON FUNCTION public.health_f21_void_workout_session(uuid,uuid,text)
TO authenticated;
GRANT EXECUTE ON FUNCTION public.health_f21_update_activity_session(uuid,uuid,text,text,timestamptz,integer,numeric,numeric,integer,integer,numeric,numeric,numeric,integer,text)
TO authenticated;
GRANT EXECUTE ON FUNCTION public.health_f21_void_activity_session(uuid,uuid,text)
TO authenticated;

-- End F21.
